const e={51:{dayName:"Dia 51 — Terça-feira",title:"Some / Any",focus:"Usar some e any para quantidades indefinidas.",vocab:[{en:"Some",pt:"Algum / Alguns (afirmativa)"},{en:"Any",pt:"Algum / Nenhum (negativa/pergunta)"},{en:"Someone",pt:"Alguém"},{en:"Anyone",pt:"Alguém (negativa/pergunta)"},{en:"Something",pt:"Algo"},{en:"Anything",pt:"Algo / Nada (neg./perg.)"},{en:"Somewhere",pt:"Em algum lugar"},{en:"Anywhere",pt:"Em qualquer lugar"},{en:"Enough",pt:"Suficiente"},{en:"Plenty",pt:"Bastante"}],grammar:{title:"Some / Any",rule:"SOME em afirmativas (I have some ideas). ANY em negativas e perguntas (Do you have any questions? I don't have any money). Em ofertas e pedidos usamos some: Would you like some coffee?",table:[{form:"Afirmativa",example:"I have some new ideas for the project.",pt:"Tenho algumas ideias novas para o projeto."},{form:"Negativa",example:"I don't have any questions.",pt:"Não tenho nenhuma pergunta."},{form:"Pergunta",example:"Do you have any experience with React?",pt:"Você tem alguma experiência com React?"}]},reading:{title:"Planning the Demo",text:"Do we have any time for a demo this week? Yes, we have some time on Friday. I have some slides ready. I don't need any more images. Is there anything missing? I don't think so. Would you like some coffee before we start? Yes, please.",translation:"Temos algum tempo para uma demonstração esta semana? Sim, temos algum tempo na sexta. Tenho alguns slides prontos. Não preciso de mais imagens. Está faltando algo? Acho que não. Gostaria de um café antes de começarmos? Sim, por favor."},quiz:[{q:"Afirmativa:",options:["I have some ideas","I have any ideas","I have any idea"],ans:"I have some ideas"},{q:"Negativa:",options:["I don't have any questions","I don't have some questions","I no have any questions"],ans:"I don't have any questions"},{q:"Oferta:",options:["Would you like some coffee?","Would you like any coffee?","You like some coffee?"],ans:"Would you like some coffee?"}],chunks:[{en:"I have some ideas",pt:"tenho algumas ideias"},{en:"do you have any questions?",pt:"você tem alguma pergunta?"},{en:"would you like some coffee?",pt:"você gostaria de um café?"}],listeningScript:"Do you have any questions about the project? No, I don't have any. But I have some suggestions. Great! Would you like some tea or coffee? Some tea, please. Is there anything else?",speakingPrompt:"Pratique: 'I have some ideas. I don't have any problems. Do you have any questions?'",lightReading:"Some/any mirror null-safety in code: some = a value exists, any = check if any value exists, none = null — existential logic in grammar.",journalPrompt:"Today is Day 51. I learned some and any.",tip:"DICA DE ESCRITA: SOME = mundo positivo; ANY = mundo negativo/pergunta. Ao escrever um e-mail pedindo algo, use: 'Could you send me some...? Do you have any...?'"},52:{dayName:"Dia 52 — Quarta-feira",title:"Much, Many & A Lot Of",focus:"Quantificar com much (incontável), many (contável) e a lot of (ambos).",vocab:[{en:"Much",pt:"Muito (incontável)"},{en:"Many",pt:"Muitos (contável)"},{en:"A lot of",pt:"Muito(s) (ambos)"},{en:"Traffic",pt:"Trânsito"},{en:"Time",pt:"Tempo"},{en:"People",pt:"Pessoas"},{en:"Problems",pt:"Problemas"},{en:"Errors",pt:"Erros"},{en:"Requests",pt:"Requisições"},{en:"Opportunities",pt:"Oportunidades"}],grammar:{title:"Much / Many / A Lot Of",rule:"MUCH + incontável em negativa/pergunta (How much time? I don't have much money). MANY + contável em qualquer caso (many users). A LOT OF funciona com os dois em afirmativas (a lot of work, a lot of apps).",table:[{form:"Much + incontável",example:"I don't have much time today.",pt:"Não tenho muito tempo hoje."},{form:"Many + contável",example:"There are many errors in the log.",pt:"Há muitos erros no log."},{form:"A lot of (ambos)",example:"We have a lot of work and a lot of requests.",pt:"Temos muito trabalho e muitas requisições."}]},reading:{title:"A Busy Day",text:"Today is a busy day. I don't have much time for lunch. There are many requests from clients. The server handles a lot of traffic. We don't have many problems, but we have a lot of work. There is not much coffee left. I need many more hours!",translation:"Hoje é um dia corrido. Não tenho muito tempo para o almoço. Há muitas solicitações de clientes. O servidor lida com muito tráfego. Não temos muitos problemas, mas temos muito trabalho. Não resta muito café. Preciso de muito mais horas!"},quiz:[{q:"Complete: 'I don't have ___ time.'",options:["much","many","a lot"],ans:"much"},{q:"Complete: 'There are ___ errors.'",options:["many","much","a lot"],ans:"many"},{q:"Complete: 'We have ___ work.'",options:["a lot of","many","much of"],ans:"a lot of"}],chunks:[{en:"I don't have much time",pt:"não tenho muito tempo"},{en:"there are many errors",pt:"há muitos erros"},{en:"the server handles a lot of traffic",pt:"o servidor lida com muito tráfego"}],listeningScript:"Do we have much time? No, we don't have much. There are many tasks today. How many clients are waiting? Many. How much coffee do we need? A lot!",speakingPrompt:"Fale sobre seu dia: 'I have a lot of work. I don't have much time. There are many tasks.'",lightReading:"Log analysis speaks quantities: too many errors, not enough memory, a lot of latency — every monitor uses much/many/a lot.",journalPrompt:"Today is Day 52. I learned much, many and a lot of.",tip:"DICA DE LEITURA: em dashboards e logs, 'too much/too many' indica excesso e 'not enough' indica falta. Essas palavras-chave dizem o estado do sistema — e do seu dia!"},53:{dayName:"Dia 53 — Quinta-feira",title:"How Much / How Many: Perguntas de Quantidade",focus:"Perguntar quantidades com how much e how many e responder com unidades.",vocab:[{en:"Weight",pt:"Peso"},{en:"Kilogram",pt:"Quilograma"},{en:"Liter",pt:"Litro"},{en:"Meter",pt:"Metro"},{en:"Kilometer",pt:"Quilômetro"},{en:"Price",pt:"Preço"},{en:"Cost",pt:"Custo / Custar"},{en:"Measure",pt:"Medir"},{en:"Cup",pt:"Xícara"},{en:"Bottle",pt:"Garrafa"}],grammar:{title:"How Much / How Many na Prática",rule:"HOW MUCH + incontável + unidade: How much milk do you need? — Two bottles. HOW MANY + contável: How many bottles are there? — Three. Responda com unidade + substantivo.",table:[{form:"How much + unidade",example:"How much coffee do we need? — Two cups.",pt:"Quanto café precisamos? — Duas xícaras."},{form:"How many",example:"How many users are online? — Five hundred.",pt:"Quantos usuários estão online? — Quinhentos."},{form:"Medidas",example:"How much RAM does the server have? — 64 GB.",pt:"Quanta RAM o servidor tem? — 64 GB."}]},reading:{title:"The Server Room",text:"How many servers are in the room? There are forty. How much memory does each server have? Each one has 64 gigabytes. How much storage do we need for the new system? About ten terabytes. How many days will the installation take? Three days. How much does it cost? Call the provider.",translation:"Quantos servidores há na sala? Há quarenta. Quanta memória cada servidor tem? Cada um tem 64 gigabytes. Quanto armazenamento precisamos para o novo sistema? Cerca de dez terabytes. Quantos dias a instalação levará? Três dias. Quanto custa? Ligue para o fornecedor."},quiz:[{q:"Complete: '___ RAM does it have?'",options:["How much","How many","How"],ans:"How much"},{q:"Complete: '___ servers are there?'",options:["How many","How much","How often"],ans:"How many"},{q:"Resposta: 'How much coffee? — ___'",options:["Two cups","Two cups coffee","Cups two"],ans:"Two cups"}],chunks:[{en:"how much memory?",pt:"quanta memória?"},{en:"how many servers?",pt:"quantos servidores?"},{en:"each server has 64 GB",pt:"cada servidor tem 64 GB"}],listeningScript:"How many computers do we need? We need fifteen. How much space does each one take? About one meter of desk. How much time will the setup take? Two hours. Perfect, thank you.",speakingPrompt:"Pergunte e responda: 'How many apps do you have? — Ten. How much time do you spend daily? — Two hours.'",lightReading:"Capacity questions are how-much/how-many questions: how much disk, how many nodes, how much bandwidth — infrastructure speaks in quantities.",journalPrompt:"Today is Day 53. I learned quantity questions with units.",tip:"DICA DE MEMÓRIA: associe MUCH à palavra 'massa' (não dá para contar: água, tempo, RAM) e MANY a 'itens' (contáveis: usuários, arquivos, servidores)."},54:{dayName:"Dia 54 — Sexta-feira",title:"A Few, A Little & Enough",focus:"Falar de pequenas quantidades e suficiência.",vocab:[{en:"A few",pt:"Alguns (contável)"},{en:"A little",pt:"Um pouco de (incontável)"},{en:"Few",pt:"Poucos (quase nenhum)"},{en:"Little",pt:"Pouco (quase nada)"},{en:"Enough",pt:"Suficiente"},{en:"Too much",pt:"Demais (incontável)"},{en:"Too many",pt:"Demais (contável)"},{en:"Minutes",pt:"Minutos"},{en:"Hours",pt:"Horas"},{en:"Days",pt:"Dias"}],grammar:{title:"A Few / A Little / Enough",rule:"A FEW + contáveis = alguns, de forma positiva (a few minutes). A LITTLE + incontáveis = um pouco (a little time). ENOUGH = suficiente (enough time, enough files). TOO MUCH/TOO MANY = demais (excessivo).",table:[{form:"A few + contável",example:"I need a few more minutes.",pt:"Preciso de mais alguns minutos."},{form:"A little + incontável",example:"There is a little milk left.",pt:"Sobrou um pouco de leite."},{form:"Enough / Too",example:"We have enough time. There are too many tasks.",pt:"Temos tempo suficiente. Há tarefas demais."}]},reading:{title:"Almost Ready",text:"The release is almost ready. We need a few more tests. There is a little risk, but nothing serious. Do we have enough time? Yes, we have enough. There are too many small bugs, but we can fix them. Give us a few hours and everything will be perfect.",translation:"O lançamento está quase pronto. Precisamos de mais alguns testes. Há um pouco de risco, mas nada sério. Temos tempo suficiente? Sim, temos. Há pequenos bugs demais, mas podemos corrigi-los. Dê-nos algumas horas e tudo ficará perfeito."},quiz:[{q:"Contável positivo:",options:["a few minutes","a little minutes","little minutes"],ans:"a few minutes"},{q:"Incontável:",options:["a little time","a few time","few time"],ans:"a little time"},{q:"'Too many bugs' significa:",options:["bugs demais","poucos bugs","nenhum bug"],ans:"bugs demais"}],chunks:[{en:"a few more tests",pt:"mais alguns testes"},{en:"we have enough time",pt:"temos tempo suficiente"},{en:"there are too many bugs",pt:"há bugs demais"}],listeningScript:"Are we ready for the release? Almost. We need a few more minutes. There is a little problem with the login. Do we have enough time to fix it? Yes, enough. Perfect.",speakingPrompt:"Use as quantidades: 'I need a few minutes. I have a little time. We have enough time. There are too many tasks.'",lightReading:"Sprint planning speaks in quantities: a few story points left, a little buffer, enough capacity, too many bugs — the vocabulary of estimation.",journalPrompt:"Today is Day 54. I learned a few, a little and enough.",tip:"DICA DE ESCRITA: 'few' (sem a) = quase nenhum; 'a few' = alguns. 'I have few ideas' (pouquíssimas) vs 'I have a few ideas' (algumas). O A muda o sentimento da frase!"},55:{dayName:"Dia 55 — Sábado",title:"Quantidades & Unidades + TESTE DE SÁBADO 8",focus:"Revisar contáveis, incontáveis e quantificadores, e testar a semana.",vocab:[{en:"Amount",pt:"Quantidade"},{en:"Total",pt:"Total"},{en:"Average",pt:"Média"},{en:"Maximum",pt:"Máximo"},{en:"Minimum",pt:"Mínimo"},{en:"Level",pt:"Nível"},{en:"Capacity",pt:"Capacidade"},{en:"Percent",pt:"Por cento"},{en:"Half",pt:"Metade"},{en:"Quarter",pt:"Quarto / Um quarto"}],grammar:{title:"Resumo da Semana 8",rule:"Contáveis (many, a few, how many), incontáveis (much, a little, how much), ambíguos (some, any, a lot of, enough).",table:[{form:"Contáveis",example:"How many users? Many users. A few users.",pt:"Quantos usuários? Muitos. Alguns."},{form:"Incontáveis",example:"How much time? Much time. A little time.",pt:"Quanto tempo? Muito. Um pouco."},{form:"Ambos",example:"Some files, some data, enough space.",pt:"Alguns arquivos, alguns dados, espaço suficiente."}]},reading:{title:"The Traffic Report",text:"This month, our website had a lot of traffic. How many visits did we have? About two million. How much time did users spend? An average of four minutes. There were a few problems with the mobile version. We have enough servers for now, but we need more capacity next year. The maximum level of users online was ten thousand. That is a great result!",translation:"Este mês, nosso site teve muito tráfego. Quantas visitas tivemos? Cerca de dois milhões. Quanto tempo os usuários passaram? Uma média de quatro minutos. Houve alguns problemas com a versão mobile. Temos servidores suficientes por enquanto, mas precisamos de mais capacidade no próximo ano. O nível máximo de usuários online foi dez mil. Esse é um ótimo resultado!"},quiz:[{q:"'A lot of traffic' — tráfego é:",options:["incontável","contável","plural"],ans:"incontável"},{q:"Complete: 'There were ___ problems.'",options:["a few","a little","much"],ans:"a few"},{q:"'We need more capacity' significa:",options:["precisamos de mais capacidade","temos capacidade demais","não precisamos de nada"],ans:"precisamos de mais capacidade"}],chunks:[{en:"a lot of traffic",pt:"muito tráfego"},{en:"an average of four minutes",pt:"uma média de quatro minutos"},{en:"we need more capacity",pt:"precisamos de mais capacidade"}],listeningScript:"Great news! The website had a lot of traffic this month. Users spent an average of four minutes. There were a few problems on mobile, but we fixed them. We have enough servers for now.",speakingPrompt:"Relate números da sua semana: 'I studied many hours. I had a little free time. I made a few mistakes. That's enough!'",lightReading:"Analytics vocabulary is quantification: visits, time on page, bounce rate — every metric answers how much or how many.",journalPrompt:"Today is Day 55. I completed my eighth Saturday Test!",tip:"DICA DE APRENDIZADO: transforme números da SUA vida em frases: 'I drink 2 cups of coffee. I sleep 7 hours. I study a little every day.' Números reais = vocabulário fixado."},56:{dayName:"Dia 56 — Domingo",title:"Revisão da Semana 8 & Checkpoint A2",focus:"Consolidar quantificadores e celebrar 8 semanas (56 dias).",vocab:[{en:"Checkpoint",pt:"Ponto de verificação"},{en:"Level",pt:"Nível"},{en:"Confidence",pt:"Confiança"},{en:"Solid",pt:"Sólido"},{en:"Foundation",pt:"Fundação"},{en:"Achievement",pt:"Conquista"},{en:"Progress",pt:"Progresso"},{en:"Consistent",pt:"Consistente"},{en:"Efficient",pt:"Eficiente"},{en:"Motivated",pt:"Motivado"}],grammar:{title:"Checkpoint 56 — Metade do A1 concluída",rule:"Oito semanas: você domina presente e contínuo, modais, frequência, pronomes, quantificadores e preposições. Próximo passo: o passado!",table:[{form:"Presente",example:"I work daily and I am studying now.",pt:"Trabalho diariamente e estou estudando agora."},{form:"Modais",example:"You should study. You can't give up.",pt:"Você deveria estudar. Você não pode desistir."},{form:"Quantidade",example:"I have a few questions and enough energy.",pt:"Tenho algumas perguntas e energia suficiente."}]},reading:{title:"Two Months of Consistency",text:"I am at my eighth-week checkpoint. My foundation is solid because I am consistent. I study a little every day, and I review a lot. I have a lot of new vocabulary and enough confidence. There are still many challenges, but I trust the process. My progress is real and visible.",translation:"Estou no meu ponto de verificação de oito semanas. Minha base é sólida porque sou consistente. Estudo um pouco todos os dias e reviso muito. Tenho muito vocabulário novo e confiança suficiente. Ainda há muitos desafios, mas confio no processo. Meu progresso é real e visível."},quiz:[{q:"'I study a little every day' — 'a little' modifica:",options:["time/esforço (incontável)","coisas contáveis","pessoas"],ans:"time/esforço (incontável)"},{q:"Complete: 'I have ___ confidence.'",options:["enough","many","a few"],ans:"enough"},{q:"'My foundation is solid' significa:",options:["minha base é sólida","minha base é fraca","não tenho base"],ans:"minha base é sólida"}],chunks:[{en:"my foundation is solid",pt:"minha base é sólida"},{en:"I trust the process",pt:"confio no processo"},{en:"my progress is real",pt:"meu progresso é real"}],listeningScript:"Congratulations! You are at your eight-week checkpoint. Your foundation is solid because you are consistent. Keep studying a little every day. The past tense is next. Trust the process!",speakingPrompt:"Autoavaliação oral: 'I am at week eight. My base is solid. I study a little every day. I trust the process.'",lightReading:"Consistency beats intensity: studying a little daily compounds like software updates — small regular patches build a stable system.",journalPrompt:"Today is Day 56. Week 8 complete. Half of A1 done — the past starts now!",tip:"DICA DE APRENDIZADO: o hábito vence a motivação. Seu progresso veio de aparecer todos os dias. Continue — o próximo módulo (passado) é onde a fluência começa a aparecer."},57:{dayName:"Dia 57 — Segunda-feira",title:"Past Simple — Verbos Regulares (+ed)",focus:"Falar de ações concluídas no passado com verbos regulares.",vocab:[{en:"Worked",pt:"Trabalhou"},{en:"Studied",pt:"Estudou"},{en:"Finished",pt:"Terminou"},{en:"Started",pt:"Começou"},{en:"Called",pt:"Ligou"},{en:"Helped",pt:"Ajudou"},{en:"Watched",pt:"Assistiu"},{en:"Listened",pt:"Ouviu"},{en:"Played",pt:"Jogou"},{en:"Lived",pt:"Morou"}],grammar:{title:"Past Simple — Regulares",rule:"Verbos regulares: verbo + -ed (work -> worked). Regras de escrita: termina em e -> +d (live -> lived); consoante+vogal+consoante -> dobra (stop -> stopped); consoante + y -> -ied (study -> studied).",table:[{form:"+ed",example:"I worked all day. She finished the task.",pt:"Trabalhei o dia todo. Ela terminou a tarefa."},{form:"+d (termina em e)",example:"He lived in São Paulo. We loved the demo.",pt:"Ele morou em São Paulo. Amamos a demo."},{form:"-y -> -ied / dobra",example:"She studied a lot. He stopped coding.",pt:"Ela estudou muito. Ele parou de programar."}]},reading:{title:"What I Did Yesterday",text:"Yesterday I worked from home. I started at eight and finished at five. I called my colleague and helped her with the new system. I watched a video about databases. I listened to a podcast at lunch. I studied English at night. I lived a normal but productive day.",translation:"Ontem trabalhei de casa. Comecei às oito e terminei às cinco. Liguei para minha colega e a ajudei com o novo sistema. Assisti a um vídeo sobre bancos de dados. Ouvi um podcast no almoço. Estudei inglês à noite. Vivi um dia normal, porém produtivo."},quiz:[{q:"Passado de 'work':",options:["worked","workt","worked-t"],ans:"worked"},{q:"Passado de 'study':",options:["studied","studyd","studied"],ans:"studied"},{q:"Passado de 'live':",options:["lived","liveed","livd"],ans:"lived"}],chunks:[{en:"I worked from home",pt:"trabalhei de casa"},{en:"she finished the task",pt:"ela terminou a tarefa"},{en:"I studied at night",pt:"estudei à noite"}],listeningScript:"Yesterday was a normal day. I started at eight and finished at five. I helped my colleague with the system. We watched a video and listened to a podcast. Everything worked well.",speakingPrompt:"Conte seu dia de ontem: 'Yesterday I studied. I worked. I watched a video. I listened to music.'",lightReading:"Changelogs live in past simple: fixed, added, removed, improved — the -ed endings narrate what happened in every release.",journalPrompt:"Today is Day 57. I learned regular past verbs.",tip:"DICA DE ESCRITA: ao narrar o passado, grampeie palavras de tempo no início: Yesterday, Last week, Two days ago. Elas preparam o leitor para o passado antes do verbo aparecer."},58:{dayName:"Dia 58 — Terça-feira",title:"Pronúncia do -ED (/t/ /d/ /id/)",focus:"Ouvir e produzir as 3 pronúncias do -ed, chave da compreensão.",vocab:[{en:"Worked",pt:"Trabalhou (/t/)"},{en:"Played",pt:"Jogou (/d/)"},{en:"Wanted",pt:"Quis (/id/)"},{en:"Needed",pt:"Precisou (/id/)"},{en:"Helped",pt:"Ajudou (/t/)"},{en:"Finished",pt:"Terminou (/t/)"},{en:"Opened",pt:"Abriu (/d/)"},{en:"Closed",pt:"Fechou (/d/)"},{en:"Started",pt:"Começou (/id/)"},{en:"Ended",pt:"Terminou (/id/)"}],grammar:{title:"As 3 Pronúncias do -ED",rule:"Depois de sons surdos (p, k, f, s): /t/ (worked = workt). Depois de sons sonoros (l, n, g, v): /d/ (played = playd). Depois de t/d: /id/ (wanted = wantid, needed = needid).",table:[{form:"/t/ (sons surdos)",example:"worked, helped, finished, stopped",pt:"trabalhou, ajudou, terminou, parou"},{form:"/d/ (sons sonoros)",example:"played, opened, closed, lived",pt:"jogou, abriu, fechou, morou"},{form:"/id/ (t e d)",example:"wanted, needed, started, ended",pt:"quis, precisou, começou, terminou"}]},reading:{title:"The Sounds of Yesterday",text:"I noticed something interesting yesterday. My colleague worked (workt) very hard. She opened (opend) the new project and started (startid) the tests. She wanted (wantid) everything perfect. We played (playd) some music and finished (finisht) on time. The team needed (needid) a break after that!",translation:"Percebi algo interessante ontem. Minha colega trabalhou muito. Ela abriu o novo projeto e começou os testes. Ela quis tudo perfeito. Tocamos um pouco de música e terminamos a tempo. A equipe precisou de uma pausa depois disso!"},quiz:[{q:"Pronúncia de 'worked':",options:["/t/","/d/","/id/"],ans:"/t/"},{q:"Pronúncia de 'played':",options:["/d/","/t/","/id/"],ans:"/d/"},{q:"Pronúncia de 'wanted':",options:["/id/","/t/","/d/"],ans:"/id/"}],chunks:[{en:"I started the tests",pt:"comecei os testes (/id/)"},{en:"she opened the project",pt:"ela abriu o projeto (/d/)"},{en:"we finished on time",pt:"terminamos a tempo (/t/)"}],listeningScript:"Yesterday I opened the office at nine. We started the new project. Everyone worked together. We finished before five. Nobody wanted to leave! The day ended perfectly.",speakingPrompt:"Repita as 3 pronúncias: 'I worked (/t/). I played (/d/). I wanted (/id/).' Repita 5 vezes cada.",lightReading:"The -ed sounds follow the same logic as terminal consonants in languages: voiceless pairs with voiceless, voiced with voiced — phonetics in action.",journalPrompt:"Today is Day 58. I learned the three sounds of -ED.",tip:"DICA DE PRONÚNCIA: para descobrir o som, coloque a mão no pescoço: sons sonoros vibram (play-DD), surdos não (work-T). Ouça e repita cada grupo 5x com o áudio do app."},59:{dayName:"Dia 59 — Quarta-feira",title:"Past Simple — Negativas com Didn't",focus:"Negar ações passadas com didn't + verbo base.",vocab:[{en:"Didn't",pt:"Não (passado)"},{en:"Arrive",pt:"Chegar"},{en:"Wait",pt:"Esperar"},{en:"Order",pt:"Pedir"},{en:"Pay",pt:"Pagar"},{en:"Buy",pt:"Comprar"},{en:"Sleep",pt:"Dormir"},{en:"Eat",pt:"Comer"},{en:"Drink",pt:"Beber"},{en:"Go",pt:"Ir"}],grammar:{title:"Negativa no Passado",rule:"DIDN'T + verbo base (sem -ed!): I didn't work, not 'didn't worked'. A forma única serve para todos: I didn't, she didn't, they didn't.",table:[{form:"didn't + verbo base",example:"I didn't work yesterday. She didn't arrive early.",pt:"Não trabalhei ontem. Ela não chegou cedo."},{form:"Atenção",example:"He didn't buy the laptop (não 'didn't bought').",pt:"Ele não comprou o notebook."},{form:"Não confunda",example:"I didn't go out last night.",pt:"Não saí ontem à noite."}]},reading:{title:"A Day Without Problems",text:"Yesterday I didn't work. It was my day off. I didn't wake up early. I didn't check my emails. I didn't order food; I cooked at home. I didn't buy anything. I didn't go out at night. I slept very well. Today I feel great!",translation:"Ontem não trabalhei. Era meu dia de folga. Não acordei cedo. Não chequei meus e-mails. Não pedi comida; cozinhei em casa. Não comprei nada. Não saí à noite. Dormi muito bem. Hoje me sinto ótimo!"},quiz:[{q:"Negativa correta:",options:["I didn't work","I didn't worked","I not worked"],ans:"I didn't work"},{q:"Complete: 'She didn't ___ early.'",options:["arrive","arrived","arriving"],ans:"arrive"},{q:"Complete: 'He didn't ___ the laptop.'",options:["buy","bought","buys"],ans:"buy"}],chunks:[{en:"I didn't work yesterday",pt:"não trabalhei ontem"},{en:"I didn't check my emails",pt:"não chequei meus e-mails"},{en:"I didn't go out",pt:"não saí"}],listeningScript:"Did you work yesterday? No, I didn't. I didn't check my emails. I didn't order food. I cooked at home. I didn't go out. I slept very well!",speakingPrompt:"Conte o que você NÃO fez: 'Yesterday I didn't study. I didn't watch TV. I didn't sleep early.'",lightReading:"Negative events are logged too: update didn't run, backup didn't complete, user didn't authenticate — logs narrate absences with didn't.",journalPrompt:"Today is Day 59. I learned negative past sentences.",tip:"DICA DE ESCRITA: com didn't, o verbo volta à forma base. A memória visual ajuda: 'didn't' + 'work', nunca 'didn't' + 'worked'. Escreva 5 negações passadas antes de dormir."},60:{dayName:"Dia 60 — Quinta-feira",title:"Past Simple — Perguntas com Did",focus:"Fazer perguntas sobre o passado com did e respostas curtas.",vocab:[{en:"Did",pt:"Auxiliar do passado"},{en:"Meet",pt:"Encontrar"},{en:"See",pt:"Ver"},{en:"Visit",pt:"Visitar"},{en:"Travel",pt:"Viajar"},{en:"Learn",pt:"Aprender"},{en:"Find",pt:"Encontrar"},{en:"Lose",pt:"Perder"},{en:"Forget",pt:"Esquecer"},{en:"Remember",pt:"Lembrar"}],grammar:{title:"Perguntas no Passado",rule:"DID + sujeito + verbo base: Did you study? Did she see the email? Respostas curtas: Yes, I did / No, she didn't. W-words: What did you do? Where did you go?",table:[{form:"Did + sujeito + verbo",example:"Did you meet the client? Yes, I did.",pt:"Você encontrou o cliente? Sim."},{form:"W-words",example:"What did you do? Where did you go?",pt:"O que você fez? Onde você foi?"},{form:"Respostas curtas",example:"Did she travel? No, she didn't.",pt:"Ela viajou? Não."}]},reading:{title:"Questions About the Weekend",text:"Did you have a good weekend? Yes, I did. Did you visit your parents? No, I didn't. I stayed home. What did you do? I fixed my laptop and learned some React. Did you find the bug? Yes, I did. It was a small error. Did you forget anything? I forgot to save the backup!",translation:"Você teve um bom fim de semana? Sim. Você visitou seus pais? Não. Fiquei em casa. O que você fez? Consertei meu notebook e aprendi um pouco de React. Você encontrou o bug? Sim. Era um erro pequeno. Esqueceu algo? Esqueci de salvar o backup!"},quiz:[{q:"Pergunta correta:",options:["Did you study?","Did you studied?","You did study?"],ans:"Did you study?"},{q:"Resposta curta de 'Did she travel?':",options:["No, she didn't.","No, she doesn't.","No, she did."],ans:"No, she didn't."},{q:"Complete: 'What ___ you do?'",options:["did","do","does"],ans:"did"}],chunks:[{en:"did you have a good weekend?",pt:"você teve um bom fim de semana?"},{en:"what did you do?",pt:"o que você fez?"},{en:"did you find the bug?",pt:"você encontrou o bug?"}],listeningScript:"Did you have a good weekend? Yes, I did. What did you do? I fixed my laptop. Did you find the problem? Yes, I did. Did you visit anybody? No, I didn't. I stayed home.",speakingPrompt:"Pergunte e responda: 'Did you study yesterday? Yes, I did. What did you eat? Did you watch a movie? No, I didn't.'",lightReading:"Debugging is a string of did-questions: did the build fail? did you pull the latest code? did the test pass? — everything happened or didn't.",journalPrompt:"Today is Day 60. I learned past questions.",tip:"DICA DE LISTENING: 'did you' soa como 'didja' na fala rápida. Ouça: 'Didja study?' = 'Did you study?'. Saber disso destrava metade das perguntas que você ouve em nativos."},61:{dayName:"Dia 61 — Sexta-feira",title:"Expressões de Tempo Passado",focus:"Usar yesterday, last week, ago e outras âncoras do passado.",vocab:[{en:"Yesterday",pt:"Ontem"},{en:"Last week",pt:"Semana passada"},{en:"Last month",pt:"Mês passado"},{en:"Last year",pt:"Ano passado"},{en:"Two days ago",pt:"Há dois dias"},{en:"A year ago",pt:"Há um ano"},{en:"On Monday",pt:"Na segunda-feira"},{en:"In 2023",pt:"Em 2023"},{en:"At 7 PM",pt:"Às 19h"},{en:"From 9 to 5",pt:"Das 9 às 5"}],grammar:{title:"Time Expressions (Passado)",rule:"YESTERDAY (ontem), LAST + período (last week, last month), AGO + período (two days ago), ON + dia (on Monday), IN + ano (in 2023), AT + hora (at 7 PM).",table:[{form:"Yesterday",example:"I finished the report yesterday.",pt:"Terminei o relatório ontem."},{form:"Last + período",example:"I started this course last month.",pt:"Comecei este curso no mês passado."},{form:"Ago",example:"We deployed the system two days ago.",pt:"Fizemos o deploy do sistema há dois dias."}]},reading:{title:"Learning Timeline",text:"I started studying English last month. In the beginning, I only knew a few words. Yesterday I read a whole article! Two months ago, I couldn't understand anything. Last week, I fixed a bug all by myself. On Monday, I gave a small presentation in English. My timeline shows real progress.",translation:"Comecei a estudar inglês no mês passado. No começo, eu só conhecia algumas palavras. Ontem li um artigo inteiro! Há dois meses, eu não entendia nada. Na semana passada, consertei um bug sozinho. Na segunda, fiz uma pequena apresentação em inglês. Minha linha do tempo mostra progresso real."},quiz:[{q:"'Two days ago' significa:",options:["há dois dias","em dois dias","por dois dias"],ans:"há dois dias"},{q:"Complete: 'I started ___ month.'",options:["last","yesterday","ago"],ans:"last"},{q:"Complete: '___ Monday I gave a presentation.'",options:["On","In","At"],ans:"On"}],chunks:[{en:"I started last month",pt:"comecei no mês passado"},{en:"two days ago",pt:"há dois dias"},{en:"on Monday",pt:"na segunda-feira"}],listeningScript:"Last month I started a new course. Two weeks ago, I finished my first project. Yesterday, I showed it to my manager. On Friday, we are going to celebrate. What a journey!",speakingPrompt:"Ancore seu passado: 'Last week I studied. Two days ago I reviewed. Yesterday I listened. On Monday I will present.'",lightReading:"System timelines use the same anchors: this deploy happened yesterday, that incident occurred last month, the audit ran two days ago.",journalPrompt:"Today is Day 61. I learned past time expressions.",tip:"DICA DE ESCRITA: comece sua narrativa com a âncora de tempo: 'Last week...', 'Yesterday...', 'Two months ago...'. Isso orienta o leitor e garante que você use o passado certinho."},62:{dayName:"Dia 62 — Sábado",title:"Passado Regular & Pronúncias + TESTE DE SÁBADO 9",focus:"Revisar o Past Simple regular completo e testar a semana.",vocab:[{en:"History",pt:"História"},{en:"Story",pt:"História / Conto"},{en:"Event",pt:"Evento"},{en:"Memory",pt:"Memória / Lembrança"},{en:"Experience",pt:"Experiência"},{en:"Success",pt:"Sucesso"},{en:"Failure",pt:"Falha"},{en:"Lesson",pt:"Lição"},{en:"Discovery",pt:"Descoberta"},{en:"Invention",pt:"Invenção"}],grammar:{title:"Resumo da Semana 9",rule:"Passado regular: +ed (worked), +d (lived), -ied (studied), dobra (stopped). Pronúncias: /t/, /d/, /id/. Negativa: didn't + base. Pergunta: Did + base.",table:[{form:"Afirmativa",example:"She worked hard and finished on time.",pt:"Ela trabalhou duro e terminou a tempo."},{form:"Negativa",example:"They didn't find the bug.",pt:"Eles não encontraram o bug."},{form:"Pergunta",example:"Did you test the system? Yes, I did.",pt:"Você testou o sistema? Sim."}]},reading:{title:"A Real Story",text:"Last year, our team faced a big failure. We launched the app, and it crashed. We didn't panic. We worked all night and studied the logs carefully. We discovered a small memory error. We fixed it and tested everything again. Yesterday, we launched the new version, and it worked perfectly. That failure was the best lesson of our career.",translation:"No ano passado, nossa equipe enfrentou uma grande falha. Lançamos o app, e ele travou. Não entramos em pânico. Trabalhamos a noite toda e estudamos os logs com cuidado. Descobrimos um pequeno erro de memória. Corrigimos e testamos tudo novamente. Ontem, lançamos a nova versão, e funcionou perfeitamente. Essa falha foi a melhor lição da nossa carreira."},quiz:[{q:"Passado de 'discover':",options:["discovered","discovered","discoverd"],ans:"discovered"},{q:"'We didn't panic' — forma correta porque:",options:["didn't + verbo base","didn't + verbo +ed","no + verbo +ed"],ans:"didn't + verbo base"},{q:"'That failure was the best lesson' significa:",options:["a falha foi a melhor lição","a falha foi um erro","não houve lição"],ans:"a falha foi a melhor lição"}],chunks:[{en:"our team faced a failure",pt:"nossa equipe enfrentou uma falha"},{en:"we studied the logs",pt:"estudamos os logs"},{en:"it worked perfectly",pt:"funcionou perfeitamente"}],listeningScript:"Last year we had a problem. The app crashed after launch. We didn't panic. We studied the logs, found the error, and fixed it. Yesterday, the new version worked perfectly. Every failure is a lesson!",speakingPrompt:"Conte sua mini-história: 'Last month I had a problem with my computer. I didn't panic. I found the error and fixed it! It worked.'",lightReading:"Postmortems are written in past simple: the incident occurred, the team investigated, we identified the root cause, we deployed the fix — history that prevents recurrence.",journalPrompt:"Today is Day 62. I completed my ninth Saturday Test!",tip:"DICA DE APRENDIZADO: conte uma história real de 1 minuto sobre um problema que você resolveu. Toda história usa: passado + negação + pergunta. Você acabou de treinar as 3 formas."},63:{dayName:"Dia 63 — Domingo",title:"Revisão da Semana 9 & Imersão Leve",focus:"Consolidar o passado regular com leitura leve e histórias.",vocab:[{en:"Pioneer",pt:"Pioneiro"},{en:"Inventor",pt:"Inventor"},{en:"Scientist",pt:"Cientista"},{en:"Engineer",pt:"Engenheiro"},{en:"Discover",pt:"Descobrir"},{en:"Create",pt:"Criar"},{en:"Design",pt:"Projetar"},{en:"Build",pt:"Construir"},{en:"Develop",pt:"Desenvolver"},{en:"Change",pt:"Mudar"}],grammar:{title:"Checkpoint 63 — Histórias no Passado",rule:"Você já narra eventos passados completos. Leia biografias simples: todas usam o passado regular o tempo todo.",table:[{form:"Advérbios",example:"They worked yesterday. He discovered it in 1945.",pt:"Eles trabalharam ontem. Ele descobriu em 1945."},{form:"Narração",example:"The team started, worked, tested, and finished.",pt:"A equipe começou, trabalhou, testou e terminou."},{form:"Pergunta",example:"Did he create the first website? Yes, he did.",pt:"Ele criou o primeiro site? Sim."}]},reading:{title:"A Pioneer of Computing",text:"Ada Lovelace lived in the 19th century. She studied mathematics and worked with Charles Babbage. She designed the first algorithm for a machine. Many people didn't understand her ideas at that time. Years later, scientists discovered her notes and changed the history of computing. She inspired many women in technology.",translation:"Ada Lovelace viveu no século XIX. Ela estudou matemática e trabalhou com Charles Babbage. Ela projetou o primeiro algoritmo para uma máquina. Muitas pessoas não entenderam suas ideias na época. Anos depois, cientistas descobriram suas anotações e mudaram a história da computação. Ela inspirou muitas mulheres na tecnologia."},quiz:[{q:"Ada Lovelace ___ o primeiro algoritmo:",options:["designed","design","designs"],ans:"designed"},{q:"'Many people didn't understand' — tempo:",options:["passado negativo","presente","futuro"],ans:"passado negativo"},{q:"'She inspired many women' significa:",options:["inspirou muitas mulheres","trabalhou com mulheres","contratou mulheres"],ans:"inspirou muitas mulheres"}],chunks:[{en:"she designed the first algorithm",pt:"ela projetou o primeiro algoritmo"},{en:"they changed the history of computing",pt:"eles mudaram a história da computação"},{en:"she inspired many women",pt:"ela inspirou muitas mulheres"}],listeningScript:"Ada Lovelace lived in the 19th century. She studied mathematics. She designed the first algorithm for a machine. People didn't understand her at that time. Today, she inspired a whole generation of women in tech.",speakingPrompt:"Conte a história da Ada em 1 minuto: 'Ada Lovelace lived... She designed... People didn't understand... She inspired...'",lightReading:"Historical figures in computing teach two things: their stories, and the past simple tense — a perfect level-A2 biography module.",journalPrompt:"Today is Day 63. Week 9 is complete. I can tell stories in the past!",tip:"DICA DE LEITURA: biografias são o melhor material A2: frases curtas, passado garantido, e você ganha cultura tech de quebra. Leia uma por semana."},64:{dayName:"Dia 64 — Segunda-feira",title:"Irregulares: Go, See, Do (Went, Saw, Did)",focus:"Aprender os primeiros verbos irregulares em contexto.",vocab:[{en:"Go / Went",pt:"Ir / Foi"},{en:"See / Saw",pt:"Ver / Viu"},{en:"Do / Did",pt:"Fazer / Fez"},{en:"Trip",pt:"Viagem"},{en:"Conference",pt:"Conferência"},{en:"Exhibition",pt:"Exposição"},{en:"Presentation",pt:"Apresentação"},{en:"Result",pt:"Resultado"},{en:"Surprise",pt:"Surpresa"},{en:"Opportunity",pt:"Oportunidade"}],grammar:{title:"Irregulares 1: Go, See, Do",rule:"Verbos irregulares mudam completamente no passado: GO -> WENT, SEE -> SAW, DO -> DID. Não adicionamos -ed. Use sempre o passado para ações concluídas: I went, she saw, we did.",table:[{form:"go -> went",example:"I went to the conference last week.",pt:"Fui à conferência na semana passada."},{form:"see -> saw",example:"She saw the new office yesterday.",pt:"Ela viu o novo escritório ontem."},{form:"do -> did",example:"We did a great presentation.",pt:"Fizemos uma ótima apresentação."}]},reading:{title:"The Conference",text:"Last week I went to a technology conference. I saw many amazing innovations. I did a short presentation about our project. My colleague went with me. She saw the future of artificial intelligence. We did our best and learned a lot. It was a fantastic experience.",translation:"Na semana passada fui a uma conferência de tecnologia. Vi muitas inovações incríveis. Fiz uma apresentação curta sobre nosso projeto. Minha colega foi comigo. Ela viu o futuro da inteligência artificial. Fizemos o nosso melhor e aprendemos muito. Foi uma experiência fantástica."},quiz:[{q:"Passado de 'go':",options:["went","goed","gone"],ans:"went"},{q:"Passado de 'see':",options:["saw","seen","seed"],ans:"saw"},{q:"Complete: 'We ___ a great presentation.'",options:["did","doed","do"],ans:"did"}],chunks:[{en:"I went to the conference",pt:"fui à conferência"},{en:"she saw the innovations",pt:"ela viu as inovações"},{en:"we did our best",pt:"fizemos o nosso melhor"}],listeningScript:"Did you go to the conference? Yes, I went last week. What did you see there? I saw many innovations. Did you do a presentation? Yes, I did. It went very well!",speakingPrompt:"Conte: 'Last week I went to the store. I saw my friend there. We did a great job.'",lightReading:"The most irregular verbs are the most frequent — go, see, do dominate everyday speech and changelogs alike.",journalPrompt:"Today is Day 64. I learned went, saw and did.",tip:"DICA DE MEMÓRIA: verbos irregulares se aprendem em TRIPLOS: base, passado, tradução (go-went-ir). Escreva o trio 3 vezes em voz alta — som + escrita + movimento fixa mais rápido."},65:{dayName:"Dia 65 — Terça-feira",title:"Irregulares: Have, Make, Take (Had, Made, Took)",focus:"Memorizar had, made e took com frases do trabalho.",vocab:[{en:"Have / Had",pt:"Ter / Tinha"},{en:"Make / Made",pt:"Fazer / Fez"},{en:"Take / Took",pt:"Pegar / Pegou"},{en:"Decision",pt:"Decisão"},{en:"Choice",pt:"Escolha"},{en:"Mistake",pt:"Erro / Engano"},{en:"Break",pt:"Pausa"},{en:"Photo",pt:"Foto"},{en:"Note",pt:"Anotação"},{en:"Time",pt:"Tempo"}],grammar:{title:"Irregulares 2: Have, Make, Take",rule:"HAVE -> HAD, MAKE -> MADE, TAKE -> TOOK. Combine com palavras comuns: had a meeting, made a decision, took a break.",table:[{form:"have -> had",example:"We had a long meeting yesterday.",pt:"Tivemos uma reunião longa ontem."},{form:"make -> made",example:"She made an important decision.",pt:"Ela tomou uma decisão importante."},{form:"take -> took",example:"I took many notes during the call.",pt:"Anotei muitas coisas durante a ligação."}]},reading:{title:"A Day of Decisions",text:"Yesterday we had a big meeting. The manager made an important decision about the project. I took notes the whole time. My colleague took photos of the whiteboard. We had a short break after two hours. Nobody made mistakes in the presentation. We took a lot of value from that day.",translation:"Ontem tivemos uma grande reunião. O gerente tomou uma decisão importante sobre o projeto. Anotei o tempo todo. Minha colega tirou fotos do quadro branco. Tivemos uma pausa curta depois de duas horas. Ninguém cometeu erros na apresentação. Tiramos muito valor daquele dia."},quiz:[{q:"Passado de 'have':",options:["had","haved","has"],ans:"had"},{q:"Passado de 'make':",options:["made","maked","mades"],ans:"made"},{q:"Complete: 'I ___ many notes.'",options:["took","taked","takes"],ans:"took"}],chunks:[{en:"we had a big meeting",pt:"tivemos uma grande reunião"},{en:"she made a decision",pt:"ela tomou uma decisão"},{en:"I took notes",pt:"tomei notas"}],listeningScript:"How was the meeting? We had a long one. What did the manager do? He made a decision. Did you take notes? Yes, I took many. Did anyone make mistakes? No, nobody did.",speakingPrompt:"Conte: 'Yesterday I had a meeting. I took notes. My team made a decision.'",lightReading:"Meeting vocabulary is made of collocations: have a standup, make a plan, take notes — fixed pairs that make past simple effortless.",journalPrompt:"Today is Day 65. I learned had, made and took.",tip:"DICA DE MEMÓRIA: aprenda o par VERBO+FALSO COGNATO: 'make a decision' (não 'do a decision'). 'Have a meeting' (não 'make'). Brasileiros acertam 90% se guardarem esses pares."},66:{dayName:"Dia 66 — Quarta-feira",title:"Irregulares: Write, Read, Build (Wrote, Read, Built)",focus:"Aprender os irregulares essenciais do mundo dev.",vocab:[{en:"Write / Wrote",pt:"Escrever / Escreveu"},{en:"Read / Read",pt:"Ler / Leu (rêd)"},{en:"Build / Built",pt:"Construir / Construiu"},{en:"Code",pt:"Código"},{en:"Documentation",pt:"Documentação"},{en:"Report",pt:"Relatório"},{en:"Feature",pt:"Funcionalidade"},{en:"System",pt:"Sistema"},{en:"Website",pt:"Site"},{en:"Application",pt:"Aplicativo"}],grammar:{title:"Irregulares 3: Write, Read, Build",rule:"WRITE -> WROTE, READ -> READ (mesma escrita, som diferente: ríd -> rèd), BUILD -> BUILT. Esses são os verbos mais usados em documentação técnica.",table:[{form:"write -> wrote",example:"I wrote the documentation yesterday.",pt:"Escrevi a documentação ontem."},{form:"read -> read (rèd)",example:"She read the report last night.",pt:"Ela leu o relatório ontem à noite."},{form:"build -> built",example:"We built the website in two weeks.",pt:"Construímos o site em duas semanas."}]},reading:{title:"The Feature That Saved Us",text:"Last month, we built a new feature for the application. I wrote the main code. My colleague read every line and found two bugs. She wrote clear documentation. The team built the tests together. When we finished, the system was much faster. We read the feedback and celebrated.",translation:"No mês passado, construímos uma nova funcionalidade para o aplicativo. Eu escrevi o código principal. Minha colega leu cada linha e encontrou dois bugs. Ela escreveu uma documentação clara. A equipe construiu os testes juntos. Quando terminamos, o sistema ficou muito mais rápido. Lemos o feedback e comemoramos."},quiz:[{q:"Passado de 'write':",options:["wrote","writed","written"],ans:"wrote"},{q:"Passado de 'build':",options:["built","builded","bult"],ans:"built"},{q:"Passado de 'read' (fala):",options:["read (rèd)","read (ríd)","readed"],ans:"read (rèd)"}],chunks:[{en:"I wrote the code",pt:"escrevi o código"},{en:"we built the website",pt:"construímos o site"},{en:"she read every line",pt:"ela leu cada linha"}],listeningScript:"What did you do last month? I wrote a lot of code. Did you build anything? Yes, we built a new feature. Did she read the docs? Yes, she read them yesterday. The system is faster now.",speakingPrompt:"Conte: 'Last week I wrote a report. I read it twice. We built a small app.'",lightReading:"Written past forms hide sound changes: read/rèd is a word that changes pronunciation without changing spelling — like some acronyms in codebases.",journalPrompt:"Today is Day 66. I learned wrote, read and built.",tip:"DICA DE LEITURA: 'read' é o único verbo que muda o SOM sem mudar a escrita. Ao ler, decida pelo contexto: se a frase fala de passado, leia como 'rèd'. Contexto é a chave."},67:{dayName:"Dia 67 — Quinta-feira",title:"Irregulares: Buy, Find, Get (Bought, Found, Got)",focus:"Aprender bought, found e got em situações práticas.",vocab:[{en:"Buy / Bought",pt:"Comprar / Comprou"},{en:"Find / Found",pt:"Encontrar / Encontrou"},{en:"Get / Got",pt:"Obter / Obteve / Recebeu"},{en:"Price",pt:"Preço"},{en:"Discount",pt:"Desconto"},{en:"Solution",pt:"Solução"},{en:"Bug",pt:"Bug / Erro"},{en:"Answer",pt:"Resposta"},{en:"Result",pt:"Resultado"},{en:"Deal",pt:"Negócio / Acordo"}],grammar:{title:"Irregulares 4: Buy, Find, Get",rule:"BUY -> BOUGHT, FIND -> FOUND, GET -> GOT. Get tem muitos usos: got an email (recebi), got a job (consegui), got tired (fiquei).",table:[{form:"buy -> bought",example:"I bought a new monitor last week.",pt:"Comprei um monitor novo na semana passada."},{form:"find -> found",example:"We found the bug in the code.",pt:"Encontramos o bug no código."},{form:"get -> got",example:"I got your email and I got the answer.",pt:"Recebi seu e-mail e obtive a resposta."}]},reading:{title:"The Smart Purchase",text:"Last week I bought a new laptop with a great discount. I found the best deal online and got free shipping. My brother got the same model last month. We found a small problem with the battery, but the store solved it. I got a perfect result: a fast laptop at a good price.",translation:"Na semana passada comprei um notebook novo com um ótimo desconto. Encontrei a melhor oferta online e consegui frete grátis. Meu irmão comprou o mesmo modelo no mês passado. Encontramos um pequeno problema com a bateria, mas a loja resolveu. Obtive um resultado perfeito: um notebook rápido por um bom preço."},quiz:[{q:"Passado de 'buy':",options:["bought","buyed","bught"],ans:"bought"},{q:"Passado de 'find':",options:["found","finded","founded"],ans:"found"},{q:"'I got your email' significa:",options:["recebi seu e-mail","perdi seu e-mail","enviarei seu e-mail"],ans:"recebi seu e-mail"}],chunks:[{en:"I bought a new monitor",pt:"comprei um monitor novo"},{en:"we found the bug",pt:"encontramos o bug"},{en:"I got your email",pt:"recebi seu e-mail"}],listeningScript:"Did you buy the new laptop? Yes, I bought it yesterday. Did you find a good price? Yes, I found a great deal. Did you get free shipping? Yes, I got it. Great purchase!",speakingPrompt:"Conte: 'Yesterday I bought a book. I found a great price. I got a discount.'",lightReading:"'Get' is the glue verb of English: get started, get it done, get the data — its past form got dominates code comments and standup talk.",journalPrompt:"Today is Day 67. I learned bought, found and got.",tip:"DICA DE MEMÓRIA: muitos irregulares vêm em RIMAS: buy-bought, bring-brought, think-thought. Agrupe por som e memorize 3 de uma vez em vez de 1."},68:{dayName:"Dia 68 — Sexta-feira",title:"Irregulares: Say, Think, Come (Said, Thought, Came)",focus:"Aprender said, thought e came para conversas e relatos.",vocab:[{en:"Say / Said",pt:"Dizer / Disse"},{en:"Think / Thought",pt:"Pensar / Pensou"},{en:"Come / Came",pt:"Vir / Veio"},{en:"Opinion",pt:"Opinião"},{en:"Truth",pt:"Verdade"},{en:"Plan",pt:"Plano"},{en:"Team",pt:"Equipe"},{en:"Customer",pt:"Cliente"},{en:"Feedback",pt:"Feedback"},{en:"Meeting",pt:"Reunião"}],grammar:{title:"Irregulares 5: Say, Think, Come",rule:"SAY -> SAID, THINK -> THOUGHT, COME -> CAME. Use para relatar o que alguém disse (he said), o que você pensou (I thought) e quem veio (they came).",table:[{form:"say -> said",example:"She said the project is ready.",pt:"Ela disse que o projeto está pronto."},{form:"think -> thought",example:"I thought the server was slow.",pt:"Pensei que o servidor estava lento."},{form:"come -> came",example:"The customers came to the demo.",pt:"Os clientes vieram para a demo."}]},reading:{title:"The Customer's Words",text:"Yesterday, a customer came to our office. He said our app is very useful. I thought he had an issue, but he came to thank us. The manager said we did a great job. We thought about his feedback and made a small improvement. It came as a wonderful surprise.",translation:"Ontem, um cliente veio ao nosso escritório. Ele disse que nosso app é muito útil. Pensei que ele tinha um problema, mas ele veio para nos agradecer. O gerente disse que fizemos um ótimo trabalho. Pensamos no feedback dele e fizemos uma pequena melhoria. Foi uma surpresa maravilhosa."},quiz:[{q:"Passado de 'say':",options:["said","sayd","sayed"],ans:"said"},{q:"Passado de 'think':",options:["thought","thinked","thoght"],ans:"thought"},{q:"Passado de 'come':",options:["came","comed","come"],ans:"came"}],chunks:[{en:"she said the project is ready",pt:"ela disse que o projeto está pronto"},{en:"I thought the server was slow",pt:"pensei que o servidor estava lento"},{en:"the customers came to the demo",pt:"os clientes vieram para a demo"}],listeningScript:"What did she say? She said it is ready. Did you think about the feedback? Yes, I thought about it. Did the client come? Yes, he came yesterday. Great news!",speakingPrompt:"Relate: 'He said hello. I thought about it. They came to the meeting.'",lightReading:"Reporting speech is said+thought: the standup says what happened, the review thinks about what to improve, the demo brings customers.",journalPrompt:"Today is Day 68. I learned said, thought and came.",tip:"DICA DE ESCRITA: ao relatar, use said + that: 'She said that the app is ready.' O 'that' é opcional, mas deixa a frase mais formal e clara em e-mails."},69:{dayName:"Dia 69 — Sábado",title:"Top 30 Irregulares + TESTE DE SÁBADO 10",focus:"Revisar a lista dos 30 irregulares essenciais e testar a semana.",vocab:[{en:"Go-Went-Gone",pt:"Ir"},{en:"See-Saw-Seen",pt:"Ver"},{en:"Do-Did-Done",pt:"Fazer"},{en:"Have-Had-Had",pt:"Ter"},{en:"Make-Made-Made",pt:"Fazer"},{en:"Take-Took-Taken",pt:"Pegar"},{en:"Write-Wrote-Written",pt:"Escrever"},{en:"Build-Built-Built",pt:"Construir"},{en:"Buy-Bought-Bought",pt:"Comprar"},{en:"Find-Found-Found",pt:"Encontrar"}],grammar:{title:"Top 30 Irregular Verbs (10 por dia)",rule:"Go-went-gone, see-saw-seen, do-did-done, have-had-had, make-made-made, take-took-taken, write-wrote-written, build-built-built, buy-bought-bought, find-found-found. Mais os 30 da semana: get-got-got, say-said-said, think-thought-thought, come-came-come.",table:[{form:"Grupo 1",example:"I went, saw, and did my best.",pt:"Fui, vi e fiz o meu melhor."},{form:"Grupo 2",example:"She had, made, and took notes.",pt:"Ela teve, fez e tomou notas."},{form:"Grupo 3",example:"He wrote, built, bought, found, got, said, thought, and came.",pt:"Ele escreveu, construiu, comprou, encontrou, obteve, disse, pensou e veio."}]},reading:{title:"The Week of Verbs",text:"This week I learned many irregular verbs. On Monday I went through the list. On Tuesday I saw the video about pronunciation. On Wednesday I wrote examples and made sentences. On Thursday I thought about real situations. On Friday I came back and reviewed everything. Now I have a solid base of thirty verbs.",translation:"Esta semana aprendi muitos verbos irregulares. Na segunda, percorri a lista. Na terça, vi o vídeo sobre pronúncia. Na quarta, escrevi exemplos e fiz frases. Na quinta, pensei em situações reais. Na sexta, voltei e revisitei tudo. Agora tenho uma base sólida de trinta verbos."},quiz:[{q:"Passado de 'get':",options:["got","getted","gat"],ans:"got"},{q:"Passado de 'think':",options:["thought","thinked","thaut"],ans:"thought"},{q:"Passado de 'say':",options:["said","sayed","seid"],ans:"said"}],chunks:[{en:"I went through the list",pt:"percorri a lista"},{en:"I reviewed everything",pt:"revisei tudo"},{en:"a solid base of verbs",pt:"uma base sólida de verbos"}],listeningScript:"This week I learned thirty irregular verbs. I went through the list every day. I wrote examples and saw the pronunciation. I thought about real situations. Now I have a solid base. Review is the key!",speakingPrompt:"Conte usando 5 irregulares: 'This week I went, saw, wrote, built and found new words.'",lightReading:"The top 30 irregular verbs cover 80% of everyday English verbs — master them and most past-tense conversations unlock.",journalPrompt:"Today is Day 69. I completed my tenth Saturday Test!",tip:"DICA DE APRENDIZADO: faça cartões mentais de 5 triplos por dia (base-passado-tradução). Revise na manhã seguinte antes de tudo. Em 6 dias, os 30 triplos estão fixados."},70:{dayName:"Dia 70 — Domingo",title:"Revisão da Semana 10 (Top 30 Irregulares)",focus:"Consolidar os 20 irregulares novos da semana com produção.",vocab:[{en:"Top 30",pt:"Top 30"},{en:"Regular",pt:"Regular"},{en:"Irregular",pt:"Irregular"},{en:"Base form",pt:"Forma base"},{en:"Past form",pt:"Forma passada"},{en:"Perfect",pt:"Perfeito"},{en:"Fluency",pt:"Fluência"},{en:"Speed",pt:"Velocidade"},{en:"Accuracy",pt:"Precisão"},{en:"Review",pt:"Revisão"}],grammar:{title:"Checkpoint 70 — A lista completa",rule:"Top 30: go-went, see-saw, do-did, have-had, make-made, take-took, write-wrote, read-read, build-built, buy-bought, find-found, get-got, say-said, think-thought, come-came + os regulares da semana passada.",table:[{form:"Contraste",example:"I worked (regular) / I went (irregular).",pt:"Eu trabalhei / eu fui."},{form:"Negativa",example:"I didn't see him. I didn't buy it.",pt:"Não o vi. Não comprei."},{form:"Pergunta",example:"Did you come alone? Yes, I did.",pt:"Você veio sozinho? Sim."}]},reading:{title:"Two Weeks of the Past",text:"In two weeks, I went from knowing zero past verbs to mastering thirty. I made a list and wrote examples. I saw my mistakes and thought about the patterns. My friends came to test me with questions. I found it fun! Now I speak about yesterday, last week, and last year with confidence.",translation:"Em duas semanas, passei de zero verbos no passado para dominar trinta. Fiz uma lista e escrevi exemplos. Vi meus erros e pensei nos padrões. Meus amigos vieram me testar com perguntas. Achei divertido! Agora falo sobre ontem, semana passada e ano passado com confiança."},quiz:[{q:"Pares corretos:",options:["go-went, see-saw","go-goed, see-seed","go-gone, see-saw"],ans:"go-went, see-saw"},{q:"'I didn't see him' — correto porque:",options:["didn't + forma base","didn't + sawn","didn't + saw"],ans:"didn't + forma base"},{q:"Complete: 'Did you come alone? — Yes, ___.'",options:["I did","I came","I do"],ans:"I did"}],chunks:[{en:"I went from zero to thirty",pt:"fui de zero a trinta"},{en:"I saw my mistakes",pt:"vi meus erros"},{en:"I speak about the past with confidence",pt:"falo sobre o passado com confiança"}],listeningScript:"You finished two weeks of past tense! You went from zero to thirty irregular verbs. You made examples and saw the patterns. Now speak about yesterday with confidence. Review is the key!",speakingPrompt:"Mini-história de 2 minutos: 'Two weeks ago I didn't know past verbs. I made a list. I saw my mistakes. I thought about patterns. Now I can speak about the past!'",lightReading:"Past-tense mastery compounds: thirty irregular verbs unlock countless combinations — like thirty reusable functions in your personal language library.",journalPrompt:"Today is Day 70. Week 10 complete! The past is now part of my toolbox.",tip:"DICA DE PRONÚNCIA: contraste os sons: come-came têm vogais diferentes. Repita pares difíceis em voz alta: went/want, saw/so, said/sed. O contraste sonoro abre seu ouvido."}},a=[{id:8,title:"Semana 8 — Contáveis & Quantificadores",daysRange:"Dias 50 a 56",subtitle:"Some/Any, Much/Many, A Few/A Little, Enough",badgeClass:"badge-purple",grammar:["Countable vs Uncountable nouns","Some / Any","Much / Many / A lot of","How much / How many + unidades","A few / A little / Enough / Too much"],vocab:"Quantidades, recursos computacionais, memória e dados (600-800 palavras)",reading:"Artigos introdutórios sobre tecnologia e operações",listening:"Escuta com números, unidades e quantidades",speaking:"Monólogo de 3 minutos sobre recursos e estudos",techBridge:"Frases: 'How much RAM do we need?', 'There are many bugs in line 12'",saturday:{recall:[["I have some ideas","tenho algumas ideias"],["do you have any questions?","você tem alguma pergunta?"],["I don't have much time","não tenho muito tempo"],["there are many errors","há muitos erros"],["the server handles a lot of traffic","o servidor lida com muito tráfego"],["how much memory?","quanta memória?"],["how many servers?","quantos servidores?"],["a few more tests","mais alguns testes"],["we have enough time","temos tempo suficiente"],["there are too many bugs","há bugs demais"],["an average of four minutes","uma média de quatro minutos"],["we need more capacity","precisamos de mais capacidade"]],reading:{title:"The Server Upgrade",text:"Our company needed a server upgrade. We had many problems with slow responses. The old server didn't have enough memory. How much RAM did we need? At least 128 gigabytes. How many users were affected? Almost ten thousand. We bought a lot of new equipment. There were some issues during the installation, but the team solved everything in a few hours. Now the system is fast and stable.",questions:["What problems did the company have?","Why did the old server fail?","How much RAM did they need?","How many users were affected?","How long did the installation take?"]},listening:"Listen: 'We needed a server upgrade. The old one didn't have enough memory. How many users were affected? Thousands. We bought new equipment. There were a few problems, but we solved them in some hours. Now the system is stable.'",speaking:"Grave 2 minutos falando sobre recursos: 'I have a lot of apps. I don't have much storage. I need a few more gigabytes...'"}},{id:9,title:"Semana 9 — Past Simple Regular",daysRange:"Dias 57 a 63",subtitle:"Verbos Regulares, Pronúncia do -ED e Did",badgeClass:"badge-emerald",grammar:["Past Simple com verbos regulares (-ed, -d, -ied)","As 3 pronúncias do -ed (/t/, /d/, /id/)","Negativas com didn't + verbo base","Perguntas com did + respostas curtas","Expressões de tempo passado (yesterday, last week, ago)"],vocab:"Eventos passados, histórico de tarefas e logs",reading:"Biografia simples: Ada Lovelace e histórias reais de trabalho",listening:"Histórias contadas no passado em velocidade natural",speaking:"Relatar o que você fez no dia anterior em inglês",techBridge:"Verbos: compiled, executed, installed, tested, created, deployed",saturday:{recall:[["I worked from home","trabalhei de casa"],["she finished the task","ela terminou a tarefa"],["I studied at night","estudei à noite"],["I started the tests","comecei os testes (/id/)"],["she opened the project","ela abriu o projeto (/d/)"],["we finished on time","terminamos a tempo (/t/)"],["I didn't work yesterday","não trabalhei ontem"],["did you find the bug?","você encontrou o bug?"],["what did you do?","o que você fez?"],["two days ago","há dois dias"],["we studied the logs","estudamos os logs"],["it worked perfectly","funcionou perfeitamente"]],reading:{title:"How I Learned to Code",text:"Two years ago, I didn't know how to code. I started with simple tutorials. I studied for one hour every day. I made many mistakes, and I learned from all of them. Last month, I finished my first real project. I showed it to my friends, and they loved it. I fixed the final bugs yesterday. I also helped my classmate start his own project. Learning is a journey that never stops.",questions:["What did the writer not know two years ago?","How much did they study daily?","When did they finish their first project?","Who liked the project?","How did they help their classmate?"]},listening:"Listen: 'Two years ago I started to learn coding. I studied one hour every day. I made mistakes and learned a lot. Last month I finished my first project. Yesterday I fixed the last bugs. My friends loved it!'",speaking:"Conte seu dia de ontem em 2 minutos: 'Yesterday I woke up... I studied... I didn't... Did you...?'"}},{id:10,title:"Semana 10 — Past Simple Irregular",daysRange:"Dias 64 a 70",subtitle:"Top 30 Verbos Irregulares",badgeClass:"badge-blue",grammar:["Top 30 irregular verbs (went, saw, did, had, made, took, wrote, read, built, bought, found, got, said, thought, came)","Expressões de tempo passado (yesterday, last week, ago)","Negativas e perguntas com verbos irregulares"],vocab:"Experiências anteriores e soluções de problemas (800-1000 palavras)",reading:"Histórias reais sobre tecnologia e conquistas",listening:"Narrações no passado com irregulares",speaking:"Descrever como você resolveu um problema no seu computador",techBridge:"Verbos: wrote code, built a system, found a bug, read docs",saturday:{recall:[["I went to the conference","fui à conferência"],["she saw the innovations","ela viu as inovações"],["we did our best","fizemos o nosso melhor"],["we had a big meeting","tivemos uma grande reunião"],["she made a decision","ela tomou uma decisão"],["I took notes","tomei notas"],["I wrote the code","escrevi o código"],["we built the website","construímos o site"],["she read every line","ela leu cada linha"],["I bought a new monitor","comprei um monitor novo"],["we found the bug","encontramos o bug"],["I got your email","recebi seu e-mail"]],reading:{title:"The Bug I Found",text:"Last Friday, the system crashed at work. I went to the office early and saw the error in the logs. I thought about the possible causes. Then I found the bug: a missing configuration. I wrote the fix and ran the tests. The manager came and said: 'Great job!' I made sure everything worked and took notes for the next time. That day I got a lot of confidence.",questions:["When did the system crash?","Where did the writer find the error?","What was the bug?","What did the manager say?","Why did the writer take notes?"]},listening:"Listen: 'Last Friday the system crashed. I went to the office early. I saw the error in the logs and found the bug. I wrote the fix. My manager came and said: Great job! I got a lot of confidence that day.'",speaking:"Conte em 2 minutos como você resolveu um problema no seu computador: 'Last week my computer... I saw... I found... I fixed... It worked!'"}}];export{e as d,a as w};
